import React, { useState, useEffect } from 'react';
import {
  Drawer, Box, Typography, TextField, Button,
  ToggleButton, ToggleButtonGroup, IconButton, Divider,
} from '@mui/material';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import { useAttivita } from '../../context/AttivitaContext';
import { useApp } from '../../context/AppContext';
import { oggiLocale } from '../../utils/helpers';

const FREQUENZE = [
  { value: 'giornaliera', label: '☀️ Giornaliera' },
  { value: 'settimanale', label: '📅 Settimanale' },
  { value: 'mensile', label: '🗓️ Mensile' },
  { value: 'specifica', label: '📌 Data specifica' },
];

const GIORNI_SETTIMANA = [
  { value: 1, label: 'Lun' }, { value: 2, label: 'Mar' }, { value: 3, label: 'Mer' },
  { value: 4, label: 'Gio' }, { value: 5, label: 'Ven' }, { value: 6, label: 'Sab' }, { value: 0, label: 'Dom' },
];

const PRIORITA = [
  { value: 'alta', label: '🔴 Alta' },
  { value: 'media', label: '🟠 Media' },
  { value: 'bassa', label: '⚪ Bassa' },
];

function AggiuntaTask({ aperto, onChiudi, attivitaInModifica }) {
  const { aggiungiAttivita, modificaAttivita, eliminaAttivita } = useAttivita();
  const { utenti } = useApp();
  const [errori, setErrori] = useState({});
  const [confermaElimina, setConfermaElimina] = useState(false);

  const assegnazioni = [
    ...utenti.map(u => ({ value: u.nome, label: `👤 ${u.nome}` })),
    { value: 'entrambi', label: '👥 Tutti' },
  ];

  const formIniziale = () => ({
    titolo: '',
    frequenza: 'giornaliera',
    giornoSettimana: 1,
    giornoMese: 1,
    dataSpecifica: '',
    dataFine: '',
    assegnato: 'entrambi',
    priorita: 'media',
  });

  const [form, setForm] = useState(formIniziale);

  useEffect(() => {
    setConfermaElimina(false);
    setErrori({});
    if (attivitaInModifica) {
      setForm({
        titolo: attivitaInModifica.titolo,
        frequenza: attivitaInModifica.frequenza,
        giornoSettimana: attivitaInModifica.giornoSettimana ?? 1,
        giornoMese: attivitaInModifica.giornoMese ?? 1,
        dataSpecifica: attivitaInModifica.dataSpecifica ?? '',
        dataFine: attivitaInModifica.dataFine ?? '',
        assegnato: attivitaInModifica.assegnato,
        priorita: attivitaInModifica.priorita ?? 'media',
      });
    } else {
      setForm(formIniziale());
    }
  }, [attivitaInModifica, aperto]);

  const aggiorna = (campo, valore) => setForm(prev => ({ ...prev, [campo]: valore }));

  const handleSubmit = () => {
    const nuoviErrori = {};
    if (!form.titolo.trim()) nuoviErrori.titolo = "Inserisci un titolo per l'attività";
    if (form.frequenza === 'specifica') {
      if (!form.dataSpecifica) {
        nuoviErrori.dataSpecifica = 'Seleziona una data';
      } else if (form.dataSpecifica < oggiLocale()) {
        nuoviErrori.dataSpecifica = 'La data non può essere nel passato';
      }
    }
    if (Object.keys(nuoviErrori).length > 0) { setErrori(nuoviErrori); return; }
    setErrori({});

    const ricorrente = form.frequenza !== 'specifica';

    const dati = {
      titolo: form.titolo.trim(),
      frequenza: form.frequenza,
      giornoSettimana: form.frequenza === 'settimanale' ? form.giornoSettimana : null,
      giornoMese: form.frequenza === 'mensile' ? form.giornoMese : null,
      dataSpecifica: form.frequenza === 'specifica' ? form.dataSpecifica : null,
      dataFine: ricorrente && form.dataFine ? form.dataFine : null,
      assegnato: form.assegnato,
      priorita: form.priorita,
    };

    if (attivitaInModifica) {
      modificaAttivita(attivitaInModifica.id, dati);
    } else {
      aggiungiAttivita(dati);
    }
    onChiudi();
  };

  const ricorrente = form.frequenza !== 'specifica';

  return (
    <Drawer
      anchor="bottom"
      open={aperto}
      onClose={onChiudi}
      PaperProps={{ sx: { borderRadius: '24px 24px 0 0', maxHeight: '92vh' } }}
    >
      <Box sx={{ p: 3, overflowY: 'auto' }}>

        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Typography variant="h6" fontWeight={700}>
            {attivitaInModifica ? '✏️ Modifica attività' : '✅ Nuova attività'}
          </Typography>
          <IconButton onClick={onChiudi} size="small"><CloseRoundedIcon /></IconButton>
        </Box>

        <TextField
          label="Titolo attività"
          fullWidth
          value={form.titolo}
          onChange={e => { aggiorna('titolo', e.target.value); setErrori(p => ({ ...p, titolo: '' })); }}
          sx={{ mb: 2 }}
          placeholder="es. Portare la spazzatura"
          error={!!errori.titolo}
          helperText={errori.titolo}
        />

        <Typography variant="subtitle2" fontWeight={600} mb={1}>Priorità</Typography>
        <ToggleButtonGroup
          value={form.priorita}
          exclusive
          onChange={(e, val) => val && aggiorna('priorita', val)}
          fullWidth
          sx={{ mb: 3 }}
        >
          {PRIORITA.map(p => (
            <ToggleButton key={p.value} value={p.value} sx={{ fontSize: '0.75rem', py: 1 }}>
              {p.label}
            </ToggleButton>
          ))}
        </ToggleButtonGroup>

        <Divider sx={{ mb: 2 }} />

        <Typography variant="subtitle2" fontWeight={600} mb={1}>Frequenza</Typography>
        <ToggleButtonGroup
          value={form.frequenza}
          exclusive
          onChange={(e, val) => val && aggiorna('frequenza', val)}
          fullWidth
          sx={{ mb: 2 }}
        >
          {FREQUENZE.map(f => (
            <ToggleButton key={f.value} value={f.value} sx={{ fontSize: '0.7rem', py: 1 }}>
              {f.label}
            </ToggleButton>
          ))}
        </ToggleButtonGroup>

        {form.frequenza === 'settimanale' && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" mb={1} display="block">Quale giorno?</Typography>
            <ToggleButtonGroup
              value={form.giornoSettimana}
              exclusive
              onChange={(e, val) => val !== null && aggiorna('giornoSettimana', val)}
              fullWidth
            >
              {GIORNI_SETTIMANA.map(g => (
                <ToggleButton key={g.value} value={g.value} sx={{ fontSize: '0.65rem', py: 0.8, minWidth: 0 }}>
                  {g.label}
                </ToggleButton>
              ))}
            </ToggleButtonGroup>
          </Box>
        )}

        {form.frequenza === 'mensile' && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" mb={1} display="block">Quale giorno del mese?</Typography>
            <TextField
              type="number" fullWidth size="small"
              value={form.giornoMese}
              onChange={e => aggiorna('giornoMese', Math.min(31, Math.max(1, parseInt(e.target.value) || 1)))}
              inputProps={{ min: 1, max: 31 }}
            />
          </Box>
        )}

        {form.frequenza === 'specifica' && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" mb={1} display="block">Seleziona la data</Typography>
            <TextField
              type="date" fullWidth size="small"
              value={form.dataSpecifica}
              onChange={e => { aggiorna('dataSpecifica', e.target.value); setErrori(p => ({ ...p, dataSpecifica: '' })); }}
              inputProps={{ min: oggiLocale() }}
              error={!!errori.dataSpecifica}
              helperText={errori.dataSpecifica}
            />
          </Box>
        )}

        {ricorrente && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" mb={1} display="block">
              Data di fine (opzionale) — l'attività smette di comparire dopo questa data
            </Typography>
            <TextField
              type="date" fullWidth size="small"
              value={form.dataFine}
              onChange={e => aggiorna('dataFine', e.target.value)}
              inputProps={{ min: oggiLocale() }}
            />
          </Box>
        )}

        <Divider sx={{ mb: 2 }} />

        <Typography variant="subtitle2" fontWeight={600} mb={1}>Assegna a</Typography>
        <ToggleButtonGroup
          value={form.assegnato}
          exclusive
          onChange={(e, val) => val && aggiorna('assegnato', val)}
          fullWidth
          sx={{ mb: 3, flexWrap: 'wrap' }}
        >
          {assegnazioni.map(a => (
            <ToggleButton key={a.value} value={a.value} sx={{ fontSize: '0.75rem', py: 1 }}>
              {a.label}
            </ToggleButton>
          ))}
        </ToggleButtonGroup>

        <Button
          fullWidth variant="contained" size="large"
          onClick={handleSubmit}
          sx={{ borderRadius: 3, py: 1.5, fontWeight: 700 }}
        >
          {attivitaInModifica ? 'Salva modifiche' : 'Aggiungi attività'}
        </Button>

        {attivitaInModifica && !confermaElimina && (
          <Button fullWidth variant="text" color="error" onClick={() => setConfermaElimina(true)} sx={{ mt: 1 }}>
            Elimina attività
          </Button>
        )}

        {confermaElimina && (
          <Box sx={{ mt: 2, p: 2, borderRadius: 2, bgcolor: 'error.light', display: 'flex', flexDirection: 'column', gap: 1 }}>
            <Typography variant="body2" fontWeight={700} color="error.contrastText">
              Sei sicuro di voler eliminare questa attività?
            </Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button fullWidth variant="outlined" onClick={() => setConfermaElimina(false)} sx={{ borderColor: 'error.contrastText', color: 'error.contrastText' }}>
                Annulla
              </Button>
              <Button fullWidth variant="contained" color="error" onClick={() => { eliminaAttivita(attivitaInModifica.id); onChiudi(); }}>
                Elimina
              </Button>
            </Box>
          </Box>
        )}
      </Box>
    </Drawer>
  );
}

export default AggiuntaTask;
